base_sources.base.cod:
using symbol "std:io" @print;
behave @print(101);
global offset::i64 = 5;
global private_offset::i64 = 99;
symbol @bias::i64;
effect @bias <- 2;
function (len)(x::i64)::i64 { x + offset }
proc read(x::i64)->i64 { x + offset + @bias }
export offset; export (len); export read; export @bias;

base_sources.adapter.cod:
export import "base.cod" offset as shift;
export import "base.cod" (len) as measure;
export import "base.cod" read as public_read;
import "base.cod" read as private_read;

base_sources.relay.cod:
export import "adapter.cod" shift as amount;
export import "adapter.cod" measure as width;
export import "adapter.cod" public_read as invoke;

base_sources.entry.cod:
using symbol "std:io" @print;
symbol from "base.cod" @bias;
effect @bias <- 7;
using "relay.cod" amount;
using "relay.cod" width;
using "relay.cod" invoke;
using "adapter.cod" measure;
behave @print(amount);
behave @print(width(3));
behave @print(measure(3));
behave @print(invoke(3));
